  const bw = dimOn ? Math.max(w, cubeBillable) : w;
  if (bw > NUMBER8_MAX_LB) return [];
  const zone = NUMBER8_ZONE_GRID[NUMBER8_ZONE_INDEX.get(oTown)][NUMBER8_ZONE_INDEX.get(dTown)];
  const band = NUMBER8_WEIGHT_BANDS.find((b) => bw <= b[0]);
