// Weight bands: [max_lb, price_cad] — upper-inclusive, per shipment on
// TOTAL actual weight.
const KNR_WEIGHT_BANDS = [
  [30, 35], [50, 40], [80, 45], [100, 50],
];
const KNR_OVER100_BASE_CAD = 50;
