function primeTimeNormCity(city) {
  let c = norm(city).replace(/\./g, '');
  c = c.replace(/\bSAINT\b/g, 'ST');
  c = c.replace(/^FT\b/, 'FORT');
  return c.replace(/\s+/g, ' ').trim();
}

function primeTimeZoneFor(destCity, destProv) {
  if (norm(destProv) !== 'AB') return null;
  const c = primeTimeNormCity(destCity);
  const keys = [c];
  const al = PRIMETIME_CITY_ALIASES[c];
  if (al) keys.push(al);
  for (const z of PRIMETIME_ZONES) {
    if (z.towns.some((t) => keys.includes(t))) return z;
  }
  return null;
}

function primeTimeHotShotRow(destCity, destProv) {
  const c = primeTimeNormCity(destCity);
  const key = PRIMETIME_CITY_ALIASES[c] || c;
  const rows = PRIMETIME_HOTSHOT_BY_TOWN.get(key) || [];
  const p = norm(destProv);
  let row = rows.find((r) => r.prov === p);
  if (!row && PRIMETIME_PROV_ALIASES[key]) {
    for (const ap of PRIMETIME_PROV_ALIASES[key]) {
      row = rows.find((r) => r.prov === ap);
      if (row) break;
    }
  }
  return row || null;
}

function primeTimeTotalVolume(packages) {
  let vol = 0;
  for (const p of Array.isArray(packages) ? packages : []) {
    const q = Math.max(1, Math.floor(Number(p.qty) || 1));
    const L = Number(p.length), W = Number(p.width), H = Number(p.height);
    if (L > 0 && W > 0 && H > 0) vol += (q * L * W * H) / 1728;
  }
  return vol;
}

// Per-item charges (Edmonton zone deliveries): first item included if under
// 20 lb; additional items $2 each, $4 for a large box (any side over 24 in
// OR volume over 2 cu ft — the average-size threshold Seven approved).
// A first item at/over 20 lb is not included, so it bills like any item.
function primeTimePerItem(packages) {
  const units = [];
  for (const p of Array.isArray(packages) ? packages : []) {
    const q = Math.max(1, Math.floor(Number(p.qty) || 1));
    const lineW = Number(p.weight_lb);
    const unitW = Number.isFinite(lineW) && lineW > 0 ? lineW / q : 0;
    const L = Number(p.length), W = Number(p.width), H = Number(p.height);
    const vol = (L > 0 && W > 0 && H > 0) ? (L * W * H) / 1728 : 0;
    const large = L > 24 || W > 24 || H > 24 || vol > 2;
    for (let i = 0; i < q; i++) units.push({ weight: unitW, large });
  }
  let total = 0;
  units.forEach((u, i) => {
    if (i === 0 && u.weight < 20) return; // first item included if under 20 lb
    total += u.large ? 4 : 2;
  });
  return total;
}

// Edmonton zone delivery quotes: one row per service level.
function primeTimeDeliveryQuotes({ destCity, destProv, weightLbs, packages, flags }) {
  const zone = primeTimeZoneFor(destCity, destProv);
  if (!zone) return [];
  const w = Number(weightLbs);
  if (!Number.isFinite(w) || w <= 0) return [];
  const perItem = primeTimePerItem(packages);
  const over = Math.max(0, w - 20) * 0.05;
  const overSize = Math.max(0, primeTimeTotalVolume(packages) - 8) * 0.50;
  const extra = Math.max(over, overSize); // higher one only (Q13)
  const f = flags || {};
  return PRIMETIME_LEVELS.map((lv, i) => {
    const addon = Math.max(
      f.residential ? PRIMETIME_ADDON_RESIDENTIAL[i] : 0,
      f.school ? PRIMETIME_ADDON_SCHOOL[i] : 0
    );
    const base = zone.prices[i] + perItem + extra + addon;
    return {
      carrier_id: PRIMETIME_ID,
      carrier_label: PRIMETIME_LABEL,
      service: `${lv.label} · ${zone.times[i]}`,
      service_level: lv.key,
      zone: zone.zone,
      weight_lbs: w,
      rate_basis: 'primetime_delivery',
      rate_cwt_used: null,
      base_cad: r2(base),
      fsc_percent: 0,
      fsc_cad: 0,
      total_cad: r2(base),
      min_charge_applied: false,
      currency: 'CAD',
      source: 'matrix',
      lane_origin_city: 'EDMONTON',
      lane_origin_prov: 'AB',
      lane_dest_city: primeTimeNormCity(destCity),
      lane_dest_prov: 'AB',
      metro_matched: false,
      notes: [],
    };
  });
}

// After-hours pickup window for a pickup datetime. Returns null during
// business hours (weekdays 7:30am–5pm) — regular rates apply then.
// The 6:00–7:30am weekday window applies in full to 7:30am (Q27) even
// though business hours start at 7:00am.
function primeTimeAfterHoursWindow(d) {
  const day = d.getDay(); // 0 Sun, 6 Sat
  const mins = d.getHours() * 60 + d.getMinutes();
  const weekend = day === 0 || day === 6;
  if (weekend) {
    if (mins < 9 * 60) return { addon: 65, label: 'Weekends Midnight–9am' };
    if (mins < 19 * 60) return { addon: 50, label: 'Weekends 9am–7pm' };
    return { addon: 55, label: 'Weekends 7pm–Midnight' };
  }
  if (mins < 6 * 60) return { addon: 60, label: 'Weekdays Midnight–6am' };
  if (mins < 7 * 60 + 30) return { addon: 30, label: 'Weekdays 6am–7:30am' };
  if (mins < 17 * 60) return null; // business hours
  if (mins < 21 * 60) return { addon: 35, label: 'Weekdays 5pm–9pm' };
  return { addon: 40, label: 'Weekdays 9pm–Midnight' };
}

// After-hours delivery quote (PT-2-PT only): zone PT-2-PT price + window
// add-on, overweight at $0.04/lb on the excess over 20 lb, oversize at
// $0.50/ft³ on the excess over 8 ft³ (higher one only, same rule as
// regular). holidayKind: null | 'stat' (+$30) | 'named' (Double Charge).
// Per-item charges are not on the after-hours sheet, so they do not apply.
// DG for after-hours is $40 (replaces $25) — the route's dgFee($25) does
// not know the pickup time; when after-hours is wired, dgFee needs
// time-awareness.
function primeTimeAfterHoursQuote({ destCity, destProv, weightLbs, packages, pickupDateTime, holidayKind }) {
  const zone = primeTimeZoneFor(destCity, destProv);
  if (!zone) return null;
  if (!(pickupDateTime instanceof Date) || Number.isNaN(pickupDateTime.getTime())) return null;
  const win = primeTimeAfterHoursWindow(pickupDateTime);
  if (!win) return null;
  const w = Number(weightLbs);
  if (!Number.isFinite(w) || w <= 0) return null;
  const over = Math.max(0, w - 20) * 0.04;
  const overSize = Math.max(0, primeTimeTotalVolume(packages) - 8) * 0.50;
  const extra = Math.max(over, overSize);
  const notes = [];
  let base;
  if (holidayKind === 'named') {
    // Double Charge = 2x (zone PT-2-PT + window add-on); weight/size extras
    // are added after doubling (Q21's own definition of the total).
    base = 2 * (zone.afterHoursPt2Pt + win.addon) + extra;
    notes.push('Double Charge holiday rate applied (2x zone + window add-on)');
  } else {
    base = zone.afterHoursPt2Pt + win.addon + extra;
    if (holidayKind === 'stat') {
      base += 30;
      notes.push('Stat holiday +$30 applied');
    }
  }
  return {
    carrier_id: PRIMETIME_ID,
    carrier_label: PRIMETIME_LABEL,
    service: `After Hours PT-2-PT · ${win.label}`,
    service_level: 'after_hours',
    zone: zone.zone,
    weight_lbs: w,
    rate_basis: 'primetime_after_hours',
    rate_cwt_used: null,
    base_cad: r2(base),
    fsc_percent: 0,
    fsc_cad: 0,
    total_cad: r2(base),
    min_charge_applied: false,
    currency: 'CAD',
    source: 'matrix',
    lane_origin_city: 'EDMONTON',
    lane_origin_prov: 'AB',
    lane_dest_city: primeTimeNormCity(destCity),
    lane_dest_prov: 'AB',
    metro_matched: false,
    notes,
  };
}

// Truck hourly: 1–3 ton and 5-ton at one rate each; full-hours billing
// after the minimum (billed = max(min, ceil(hours))).
function primeTimeTruckQuote({ vehicleClass, hours, afterHours }) {
  const cls = String(vehicleClass || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  const is5 = cls === 'ton5' || cls === '5ton' || cls === '5';
  const rate = afterHours ? (is5 ? 85 : 75) : (is5 ? 90 : 80);
  const min = afterHours ? 3 : 2;
  const h = Number(hours);
  if (!Number.isFinite(h) || h <= 0) return null;
  const billed = Math.max(min, Math.ceil(h));
  return {
    vehicle_class: is5 ? '5 Ton' : '1-3 Ton',
    rate_per_hr: rate,
    min_hours: min,
    billed_hours: billed,
    base_cad: r2(billed * rate),
    after_hours: !!afterHours,
  };
}

// Hot-shot quote: vehicle auto-selected (smallest whose included weight
// covers the load). Over 1000 lb: 3 & 5 Ton + $0.05/lb over 1000.
// +$100 on ALL outside-Alberta destinations. Airport $70 max per shipment
// (flags.airport — no input in the flow yet). Ferry on top of Victoria.
// Waiting and 2nd-driver hours have no input in the flow, so they are
// noted, not priced. Edmonton-sheet extras do NOT apply on hot-shot trips.
function primeTimeHotShotQuote({ destCity, destProv, weightLbs, packages, flags }) {
  const row = primeTimeHotShotRow(destCity, destProv);
  if (!row) return null;
  const w = Number(weightLbs);
  if (!Number.isFinite(w) || w <= 0) return null;
  const f = flags || {};
  let vehicle = PRIMETIME_VEHICLES.find((v) => w <= v.includedLb);
  let overage = 0;
  if (!vehicle) {
    vehicle = PRIMETIME_VEHICLES[PRIMETIME_VEHICLES.length - 1];
    overage = (w - 1000) * 0.05;
  }
  let base = vehicle.base + vehicle.perKm * row.km + overage;
  const notes = [];
  if (row.prov !== 'AB') base += 100;
  if (f.airport) base += 70;
  if (row.town === 'VICTORIA' && row.prov === 'BC') {
    base += vehicle.ferry;
    notes.push('Ferry waiting time may apply (not billed)');
  }
  if (row.km > 1300) notes.push('2nd driver $50/hr applies on this trip — duration needed to price');
  notes.push('After-hours km surcharge (+$0.20/km on km driven outside business hours) not included — pickup time needed');
  return {
    carrier_id: PRIMETIME_ID,
    carrier_label: PRIMETIME_LABEL,
    service: `Hot Shot · ${vehicle.label}`,
    service_level: 'hotshot',
    vehicle_class: vehicle.key,
    zone: row.town,
    weight_lbs: w,
    rate_basis: 'primetime_hotshot',
    rate_cwt_used: null,
    base_cad: r2(base),
    fsc_percent: 0,
    fsc_cad: 0,
    total_cad: r2(base),
    min_charge_applied: false,
    currency: 'CAD',
    source: 'matrix',
    lane_origin_city: 'EDMONTON',
    lane_origin_prov: 'AB',
    lane_dest_city: row.town,
    lane_dest_prov: row.prov,
    metro_matched: false,
    notes,
  };
}

function isGuilbaultPalletLine(p) {
  const L = Number(p.length), W = Number(p.width);
  return (L === 48 && W === 40) || (L === 40 && W === 48);
}

function guilbaultBillableWeight(actualLbs, packages, floorLbPerCuFt) {
  const w = Number(actualLbs);
  const floor = Number(floorLbPerCuFt) > 0 ? Number(floorLbPerCuFt) : DENSITY_FLOOR_LB_PER_CUFT;
  let pallets = 0, cubeFt = 0, looseFootprint = 0, dimLines = 0;
  for (const p of packages || []) {
    const q = Math.max(1, Math.floor(Number(p.qty) || 1));
    const L = Number(p.length), W = Number(p.width), H = Number(p.height);
    if (!(L > 0 && W > 0 && H > 0)) continue;
    dimLines++;
    cubeFt += (q * L * W * H) / 1728;
    if (isGuilbaultPalletLine(p)) pallets += q;
    else looseFootprint += ((q * L * W) / 144) * (p.stackable ? 0.5 : 1);
  }
  const palletFt = Math.ceil(pallets / 2) * 4;
  const looseFt = (looseFootprint / TRAILER_WIDTH_FT) * (GUILBAULT_LOOSE_LB_PER_ENGINE_FT / GUILBAULT_LB_PER_FT);
  const linearFt = palletFt + looseFt;
  let billable, rule;
  if (pallets > 0 && linearFt >= GUILBAULT_LF_THRESHOLD_FT) {
    billable = Math.max(w, linearFt * GUILBAULT_LB_PER_FT);
    rule = 'guilbault_linear_foot';
  } else if (pallets > 0) {
    billable = Math.max(w, pallets * GUILBAULT_LB_PER_PALLET_SPACE, cubeFt * floor);
    rule = 'guilbault_pallet_space';
  } else {
    billable = Math.max(w, cubeFt * floor,
      (looseFootprint / TRAILER_WIDTH_FT) * GUILBAULT_LOOSE_LB_PER_ENGINE_FT);
    rule = 'guilbault_loose_footprint';
  }
  return {
    billable_lbs: r2(billable),
    actual_lbs: r2(w),
    cube_ft: r2(cubeFt),
    linear_ft: r2(linearFt),
    density_pcf: cubeFt > 0 ? r2(w / cubeFt) : null,
    floor_lb_per_cuft: floor,
    dimensional_applied: billable > w,
    dimensional_rule: rule,
    dim_lines: dimLines,
    pallet_count: pallets,
    guilbault_tl: pallets >= GUILBAULT_TL_MIN_PALLETS
      || linearFt >= GUILBAULT_LF_THRESHOLD_FT
      || billable >= GUILBAULT_TL_MIN_LB,
  };
}

// Rate one shipment across every matching lane; cheapest first.
// Rating math (weight lanes): first break with billableLbs <= max_lb;
// base = max(min_charge, billableLbs/100 * rate_cwt); fsc = base * fsc%/100; total = base + fsc.
// Flat-band lanes (e.g. Gardewine 2026): when billableLbs falls in a
// lane.flat_bands entry, that entry's per-shipment price IS the base —
// no CWT math, no minimum-charge floor. Above the last flat band the lane
// falls through to its CWT breaks; above the last break there is no quote
// (the sheet publishes no rate for that weight).
// billableLbs = max(actual lb, cube_ft x density floor, linear_ft x 1000 when over
// the linear threshold) — see billableWeight(). With no dimensions it == actual.
// Skid lanes (lane.skid_rates): flat per-shipment price for the exact skid count;
// they only rate when a matching skidCount is supplied. Money rounded to 2 decimals.
// Per-unit lanes (lane.per_unit_bands): price per unit by the unit's weight band
// (line weight / qty); shipment base = sum over lines of band price x qty.
// Flat per-piece lanes (lane.flat_per_piece_cad): one flat rate per piece,
// no weight rating; billable pieces = max(total package qty, lane.min_pieces).
// Tiered per-piece lanes (lane.per_piece_tiers): each line is priced by its
// overall diameter = max(length, width, height) in inches — e.g. Bee Express
// regular (OD <= 35"), MT (OD <= 41.5"), Semi (OD above). A line with no dims
// falls back to the first (regular) tier.
// Dimensional weight never applies to any of these.
function quoteMatrix({ originCity, originProv, destCity, destProv, weightLbs, skidCount, packages, pickupDateTime, originStreet, destStreet }) {
  const st = ensureLoaded();
  const oCity = norm(originCity);
  const oProv = norm(originProv);
  const dCity = norm(destCity);
  const dProv = norm(destProv);
  const w = Number(weightLbs);
  if (!oCity || !dCity || !Number.isFinite(w) || w <= 0) return [];
  const _sk = Number(skidCount);
  const skids = Number.isInteger(_sk) && _sk > 0 ? _sk : null;

  const quotes = [];
  for (const lane of st.data.lanes) {
    if (!placeMatches(lane.origin_city, lane.origin_prov, oCity, oProv)) continue;
    if (!placeMatches(lane.dest_city, lane.dest_prov, dCity, dProv)) continue;
    const carrier = st.carriersById.get(lane.carrier_id);

    // Skid-based lane: flat price for the exact skid count, no weight rating.
    if (lane.skid_rates) {
      const flat = skids != null ? lane.skid_rates[skids] : undefined;
      if (!(flat > 0)) continue;
      const fscPercent = fscFor(carrier, w);
      const fsc = flat * fscPercent / 100;
      quotes.push({
        carrier_id: lane.carrier_id,
        carrier_label: carrier ? carrier.carrier_label : lane.carrier_id,
        service: `LTL \u00b7 ${skids} skids`,
        weight_lbs: w,
        skids,
        rate_basis: 'skid',
        rate_cwt_used: null,
        base_cad: r2(flat),
        fsc_percent: fscPercent,
        fsc_cad: r2(fsc),
        total_cad: r2(flat + fsc),
        min_charge_applied: false,
        currency: 'CAD',
        source: 'matrix',
        lane_origin_city: lane.origin_city,
        lane_origin_prov: lane.origin_prov,
        lane_dest_city: lane.dest_city,
        lane_dest_prov: lane.dest_prov,
        metro_matched:
          lane.origin_city !== oCity || lane.dest_city !== dCity,
      });
      continue;
    }

    // Per-unit lanes (e.g. Rockfall Freightways tire rates): the sheet prices
    // PER UNIT by the unit's weight band. Each package line is rated on its
    // own per-unit weight (line weight / qty); the shipment base is the sum
    // of the line bases. A line whose per-unit weight falls outside every
    // published band has no rate, so the lane gives no quote. Dimensional
    // weight never applies here — the sheet prices on actual unit weight.
    if (lane.per_unit_bands) {
      const lines = Array.isArray(packages) ? packages : [];
      let base = 0;
      let rated = lines.length > 0;
      for (const p of lines) {
        const q = Math.max(1, Math.floor(Number(p.qty) || 1));
        const lineW = Number(p.weight_lb);
        if (!Number.isFinite(lineW) || lineW <= 0) { rated = false; break; }
        const unitW = lineW / q;
        const band = (lane.per_unit_bands || []).find(
          (b) => unitW <= b.max_lb && unitW >= (b.min_lb || 0)
        );
        if (!band || !(band.price_cad > 0)) { rated = false; break; }
        base += band.price_cad * q;
      }
      if (!rated) continue;
      const fscPercent = fscFor(carrier, w);
      const fsc = base * fscPercent / 100;
      quotes.push({
        carrier_id: lane.carrier_id,
        carrier_label: carrier ? carrier.carrier_label : lane.carrier_id,
        service: 'LTL',
        weight_lbs: w,
        rate_basis: 'per_unit',
        rate_cwt_used: null,
        base_cad: r2(base),
        fsc_percent: fscPercent,
        fsc_cad: r2(fsc),
        total_cad: r2(base + fsc),
        min_charge_applied: false,
        currency: 'CAD',
        source: 'matrix',
        lane_origin_city: lane.origin_city,
        lane_origin_prov: lane.origin_prov,
        lane_dest_city: lane.dest_city,
        lane_dest_prov: lane.dest_prov,
        metro_matched:
          lane.origin_city !== oCity || lane.dest_city !== dCity,
      });
      continue;
    }

    // Flatlander Express: first/additional tire pricing + tractor flats.
    // Lines select their tire family via package_type. A line with any other
    // package_type (including generic 'Tire') gets no Flatlander quote.
    if (lane.flatlander) {
      const lines = Array.isArray(packages) ? packages : [];
      let rated = lines.length > 0;
      let base = 0;
      const counts = { passenger: 0, semi: 0, implement: 0 };
      for (const p of lines) {
        const q = Math.max(1, Math.floor(Number(p.qty) || 1));
        const fam = FLATLANDER_PKG_TYPE[norm(p.package_type)];
        if (!fam) { rated = false; break; }
        if (fam === 'tractor') {
          const dims = [Number(p.length), Number(p.width), Number(p.height)];
          if (dims.some((d) => !(d > 0))) { rated = false; break; }
          base += flatlanderTractorPrice(Math.max(...dims), Math.min(...dims)) * q;
        } else {
          counts[fam] += q;
        }
      }
      if (rated) {
        const present = Object.keys(counts).filter((t) => counts[t] > 0);
        if (present.length > 0) {
          // One shared first-tire slot at the highest first price present.
          const firstType = present.reduce((a, b) => (FLATLANDER_FIRST[a] >= FLATLANDER_FIRST[b] ? a : b));
          base += FLATLANDER_FIRST[firstType];
          for (const t of present) {
            base += (counts[t] - (t === firstType ? 1 : 0)) * FLATLANDER_ADD[t];
          }
        }
        // Off-route service point: flat charge "added to the rate" (per
        // Flatlander, Stacey Ashurst 2026-10-16) — joins the base, so FSC
        // applies to the combined rate.
        if (lane.off_route_cad) base += lane.off_route_cad;
      }
      if (!rated) continue;
      const fscPercent = fscFor(carrier, w);
      const fsc = base * fscPercent / 100;
      quotes.push({
        carrier_id: lane.carrier_id,
        carrier_label: carrier ? carrier.carrier_label : lane.carrier_id,
        service: 'LTL',
        weight_lbs: w,
        rate_basis: 'flatlander',
        rate_cwt_used: null,
        base_cad: r2(base),
        fsc_percent: fscPercent,
        fsc_cad: r2(fsc),
        total_cad: r2(base + fsc),
        min_charge_applied: false,
        currency: 'CAD',
        source: 'matrix',
        lane_origin_city: lane.origin_city,
        lane_origin_prov: lane.origin_prov,
        lane_dest_city: lane.dest_city,
        lane_dest_prov: lane.dest_prov,
        metro_matched:
          lane.origin_city !== oCity || lane.dest_city !== dCity,
        ...(lane.off_route_cad ? { off_route_cad: lane.off_route_cad } : {}),
        ...(lane.service_note ? { service_note: lane.service_note } : {}),
      });
      continue;
    }

    // PA Express: flat per-shipment weight bands on actual weight.
    if (lane.paexpress) {
      const lines = Array.isArray(packages) ? packages : [];
      if (lines.length === 0) continue;
      let base;
      const allEnvelope = lines.every((p) => norm(p.package_type) === 'ENVELOPE');
      if (allEnvelope) {
        base = PA_ENVELOPE_CAD;
      } else {
        if (!(w > 0) || w > 1000) continue;
        const band = PA_WEIGHT_BANDS.find((b) => w <= b[0]);
        if (!band) continue;
        base = band[1];
      }
      const fscPercent = fscFor(carrier, w);
      const fsc = base * fscPercent / 100;
      quotes.push({
        carrier_id: lane.carrier_id,
        carrier_label: carrier ? carrier.carrier_label : lane.carrier_id,
        service: 'LTL',
        weight_lbs: w,
        rate_basis: 'paexpress',
        rate_cwt_used: null,
        base_cad: r2(base),
        fsc_percent: fscPercent,
        fsc_cad: r2(fsc),
        total_cad: r2(base + fsc),
        min_charge_applied: false,
        currency: 'CAD',
        source: 'matrix',
        lane_origin_city: lane.origin_city,
        lane_origin_prov: lane.origin_prov,
        lane_dest_city: lane.dest_city,
        lane_dest_prov: lane.dest_prov,
        metro_matched:
          lane.origin_city !== oCity || lane.dest_city !== dCity,
      });
      continue;
    }

    // Flat per-piece lanes (e.g. Bee Express Total Tire): one flat rate per
    // piece, no weight rating. Billable pieces = max(total package qty,
    // lane.min_pieces). Dimensional weight never applies here.
    // Tiered lanes (lane.per_piece_tiers): each line is priced by its overall
    // diameter = max(length, width, height) in inches. A line with no dims
    // falls back to the first (regular) tier.
    // Bee Express farm tires: a line whose per-piece weight is 150-1000 lb
    // bills at the farm weight-band rate (see BEE_FARM_BANDS); under 150 lb
    // uses the OD tiers; over 1000 lb per piece gets no quote.
    if (lane.flat_per_piece_cad || lane.per_piece_tiers) {
      const lines = Array.isArray(packages) ? packages : [];
      let pieces = 0;
      let base = 0;
      let rated = lines.length > 0;
      let firstPrice = null;
      const tiers = Array.isArray(lane.per_piece_tiers) ? lane.per_piece_tiers : null;
      for (const p of lines) {
        const q = Math.max(1, Math.floor(Number(p.qty) || 1));
        pieces += q;
        let price;
        // Bee Express farm tires: per-piece weight drives the rate.
        const lineW = Number(p.weight_lb);
        const unitW = Number.isFinite(lineW) && lineW > 0 ? lineW / q : 0;
        if (lane.carrier_id === BEE_ID && tiers && unitW > BEE_FARM_MAX_LB) {
          rated = false; break;
        }
        if (lane.carrier_id === BEE_ID && tiers && unitW >= BEE_FARM_MIN_LB) {
          price = beeFarmBandPrice(Number(tiers[0] && tiers[0].price_cad) || 0, unitW);
        } else if (tiers) {
          const L = Number(p.length), W = Number(p.width), H = Number(p.height);
          const od = (L > 0 && W > 0 && H > 0) ? Math.max(L, W, H) : 0;
          const tier = tiers.find((t) => od <= Number(t.max_od_in)) || tiers[tiers.length - 1];
          price = Number(tier && tier.price_cad) || 0;
        } else {
          price = lane.flat_per_piece_cad;
        }
        if (!(price > 0)) { rated = false; break; }
        if (firstPrice == null) firstPrice = price;
        base += price * q;
      }
      if (!rated) continue;
      const minPieces = Math.max(1, Math.floor(Number(lane.min_pieces) || 1));
      const billed = Math.max(pieces, minPieces);
      // Min-pieces shortfall bills at the first line's tier price.
      if (billed > pieces) base += (billed - pieces) * (firstPrice || 0);
      const fscPercent = fscFor(carrier, w);
      const fsc = base * fscPercent / 100;
      quotes.push({
        carrier_id: lane.carrier_id,
        carrier_label: carrier ? carrier.carrier_label : lane.carrier_id,
        service: 'LTL',
        weight_lbs: w,
        rate_basis: 'per_piece',
        rate_cwt_used: null,
        base_cad: r2(base),
        fsc_percent: fscPercent,
        fsc_cad: r2(fsc),
        total_cad: r2(base + fsc),
        min_charge_applied: billed > pieces,
        currency: 'CAD',
        source: 'matrix',
        lane_origin_city: lane.origin_city,
        lane_origin_prov: lane.origin_prov,
        lane_dest_city: lane.dest_city,
        lane_dest_prov: lane.dest_prov,
        metro_matched:
          lane.origin_city !== oCity || lane.dest_city !== dCity,
      });
      continue;
    }

    // Dimensional weight with this carrier's density floor (admin override
    // or the global default) — skipped entirely when dim weight is turned
    // off for the carrier (rates on actual weight). Rating weight:
    // dimensional when bulky.
    // Guilbault rates on pallet positions (Naud tariff), not footprint area.
    const dim = lane.carrier_id === GUILBAULT_ID
      ? guilbaultBillableWeight(w, packages, densityFloorFor(lane.carrier_id))
      : billableWeight(w, packages, densityFloorFor(lane.carrier_id));
    const dimOn = dimWeightEnabledFor(lane.carrier_id);
    const bw = dimOn ? dim.billable_lbs : dim.actual_lbs;
    // Guilbault TL surcharge table: 6+ pallets, 12+ trailer feet, or 10,000+ lb.
    const tlHint = lane.carrier_id === GUILBAULT_ID && dimOn && dim.guilbault_tl === true;
    // Flat per-shipment band wins when the billable weight falls in one;
    // otherwise CWT breaks; no band and no break means no quote.
    // A band may carry an optional min_lb (a sheet gap, e.g. Gardewine
    // Winnipeg→Churchill publishes no rate under 500 lb); bands without
    // min_lb rate from 0, as before.
    const flat = (lane.flat_bands || []).find((b) => bw <= b.max_lb && bw >= (b.min_lb || 0));
    let base, rateCwtUsed, minApplied, rateBasis;
    if (flat && flat.price_cad > 0) {
      base = flat.price_cad;
      rateCwtUsed = null;
      minApplied = false;
      rateBasis = 'flat';
    } else {
      const brk = (lane.breaks || []).find((b) => bw <= b.max_lb && bw >= (b.min_lb || 0));
      if (!brk || !(brk.rate_cwt > 0)) continue;
      const raw = (bw / 100) * brk.rate_cwt;
      minApplied = raw < lane.min_charge_cad;
      base = minApplied ? lane.min_charge_cad : raw;
      rateCwtUsed = brk.rate_cwt;
      rateBasis = undefined;
    }
    // MAX F/L cap (e.g. J&R Hall Nov 1 2026 tariff): the line-haul base never
    // exceeds the lane's max_charge_cad. Applies after the min-charge floor,
    // before FSC (FSC is computed on the capped base).
    const maxApplied = Number(lane.max_charge_cad) > 0 && base > lane.max_charge_cad;
    if (maxApplied) base = lane.max_charge_cad;
    const fscPercent = fscFor(carrier, bw, tlHint);
    const fsc = base * fscPercent / 100;

    quotes.push({
      carrier_id: lane.carrier_id,
      carrier_label: carrier ? carrier.carrier_label : lane.carrier_id,
      service: 'LTL',
      weight_lbs: w,
      billable_weight_lbs: bw,
      density_pcf: dim.density_pcf,
      cube_ft: dim.cube_ft,
      linear_ft: dim.linear_ft,
      floor_lb_per_cuft: dim.floor_lb_per_cuft,
      pallet_count: dim.pallet_count != null ? dim.pallet_count : null,
      guilbault_tl: !!dim.guilbault_tl,
      dimensional_applied: dimOn && dim.dimensional_applied,
      dimensional_rule: dimOn ? dim.dimensional_rule : 'actual',
      dim_weight_enabled: dimOn,
      rate_cwt_used: rateCwtUsed,
      ...(rateBasis ? { rate_basis: rateBasis } : {}),
      base_cad: r2(base),
      fsc_percent: fscPercent,
      fsc_cad: r2(fsc),
      total_cad: r2(base + fsc),
      min_charge_applied: minApplied,
      max_charge_applied: maxApplied,
      currency: 'CAD',
      source: 'matrix',
      // Actual lane cities that rated this quote; when the quoted city is a
      // metro alias (e.g. Acheson -> Edmonton) these differ from the input.
      lane_origin_city: lane.origin_city,
      lane_origin_prov: lane.origin_prov,
      lane_dest_city: lane.dest_city,
      lane_dest_prov: lane.dest_prov,
      metro_matched:
        lane.origin_city !== oCity || lane.dest_city !== dCity,
    });
  }
  // Prime Time Courier: dedicated rating path (no matrix lanes).
  // Edmonton origin only; destination cities match exactly. When a pickup
  // datetime is supplied and it falls in an after-hours window, the
  // after-hours quote replaces the regular delivery rows. The quote flow
  // carries no pickup time yet, so it quotes regular-hours rates.
  if (oCity === 'EDMONTON' && oProv === 'AB') {
    const ptFlags = { residential: false, school: false, airport: false };
    const ptAfter = pickupDateTime instanceof Date && !Number.isNaN(pickupDateTime.getTime())
      ? primeTimeAfterHoursQuote({ destCity: dCity, destProv: dProv, weightLbs: w, packages, pickupDateTime })
      : null;
    if (ptAfter) {
      quotes.push(ptAfter);
    } else {
      for (const q of primeTimeDeliveryQuotes({ destCity: dCity, destProv: dProv, weightLbs: w, packages, flags: ptFlags })) quotes.push(q);
    }
    const ptHot = primeTimeHotShotQuote({ destCity: dCity, destProv: dProv, weightLbs: w, packages, flags: ptFlags });
    if (ptHot) quotes.push(ptHot);
  }
  // Number 8 Freight: dedicated zone-matrix rating path (no matrix lanes).
  // BC-only; both cities must be Number 8 matrix towns (exact match after
  // normalization — no metro collapsing and no nearby-town fallback).
  if ((oProv === 'BC' || oProv === '') && (dProv === 'BC' || dProv === '')) {
    for (const q of number8Quotes({ originCity: oCity, originProv: oProv, destCity: dCity, destProv: dProv, weightLbs: w, packages, originStreet, destStreet })) quotes.push(q);
  }
  // Done Deal Delivery: flat weight-table rating, no lanes/zones.
  // AB-only; both cities must be in the 26-point Calgary-region service
  // area (exact match after normalization — no metro collapsing, no
  // nearby-town fallback).
  if ((oProv === 'AB' || oProv === '') && (dProv === 'AB' || dProv === '')) {
    for (const q of doneDealQuotes({ originCity: oCity, originProv: oProv, destCity: dCity, destProv: dProv, weightLbs: w, packages })) quotes.push(q);
  }
  // KNR Courier: flat weight-table rating, no lanes/zones.
  // SK-only; both cities must be in the 13-town Hwy 48 corridor service
  // area (exact match after normalization — no metro collapsing, no
  // nearby-town fallback). All-tire shipments price per piece instead.
  if ((oProv === 'SK' || oProv === '') && (dProv === 'SK' || dProv === '')) {
    for (const q of knrQuotes({ originCity: oCity, originProv: oProv, destCity: dCity, destProv: dProv, weightLbs: w, packages })) quotes.push(q);
  }
  // TEAMS Transport: dedicated linear-foot flat rating (no matrix lanes).
  // Both ends must resolve to one of the 8 terminals via the standard
  // matrix place-matching (incl. metro collapsing).
  for (const q of teamsQuotes({ originCity: oCity, originProv: oProv, destCity: dCity, destProv: dProv, weightLbs: w, packages })) quotes.push(q);
  quotes.sort((a, b) => a.total_cad - b.total_cad || a.carrier_id.localeCompare(b.carrier_id));
  return quotes;
}

// Full-load (FTL) rating for full-load-scale shipments (see fullLoadCheck).
// Carriers price FTL per truck: billable = max(actual, FTL_MIN_LB), rated at the
// lane's 20,000-lb break ("20,000 lb pricing"), FSC at the carrier's TL percent
// (Admin TL override wins via fscFor). Lanes without a genuine 20,000+ break
// are skipped — no FTL rate on file, no quote.
const FTL_MIN_LB = numEnv('FTL_MIN_LB', 20000);
function quoteFtl({ originCity, originProv, destCity, destProv, weightLbs, packages }) {
  const st = ensureLoaded();
  const oCity = norm(originCity);
  const oProv = norm(originProv);
  const dCity = norm(destCity);
  const dProv = norm(destProv);
  const w = Number(weightLbs);
  if (!oCity || !dCity || !Number.isFinite(w) || w <= 0) return [];
  const bw = Math.max(w, FTL_MIN_LB);

  const quotes = [];
  for (const lane of st.data.lanes) {
    if (!placeMatches(lane.origin_city, lane.origin_prov, oCity, oProv)) continue;
    if (!placeMatches(lane.dest_city, lane.dest_prov, dCity, dProv)) continue;
    if (lane.skid_rates) continue; // FTL is weight-rated, not skid-rated
    const carrier = st.carriersById.get(lane.carrier_id);
    const breaks = lane.breaks || [];
    const last = breaks[breaks.length - 1];
    if (!last || !(last.max_lb >= 20000) || !(last.rate_cwt > 0)) continue;
    const dim = billableWeight(w, packages, densityFloorFor(lane.carrier_id));
    let base = (bw / 100) * last.rate_cwt;
    // MAX F/L cap (e.g. J&R Hall Nov 1 2026 tariff) applies to FTL too.
    const maxApplied = Number(lane.max_charge_cad) > 0 && base > lane.max_charge_cad;
    if (maxApplied) base = lane.max_charge_cad;
    const fscPercent = fscFor(carrier, bw);
    const fsc = base * fscPercent / 100;
    quotes.push({
      carrier_id: lane.carrier_id,
      carrier_label: carrier ? carrier.carrier_label : lane.carrier_id,
      service: 'FTL',
      weight_lbs: w,
      billable_weight_lbs: bw,
      density_pcf: dim.density_pcf,
      cube_ft: dim.cube_ft,
      linear_ft: dim.linear_ft,
      floor_lb_per_cuft: dim.floor_lb_per_cuft,
      dimensional_applied: false,
      dimensional_rule: 'ftl',
      rate_basis: 'ftl',
      rate_cwt_used: last.rate_cwt,
      base_cad: r2(base),
      fsc_percent: fscPercent,
      fsc_cad: r2(fsc),
      total_cad: r2(base + fsc),
      min_charge_applied: false,
      max_charge_applied: maxApplied,
      currency: 'CAD',
      source: 'matrix',
      lane_origin_city: lane.origin_city,
      lane_origin_prov: lane.origin_prov,
      lane_dest_city: lane.dest_city,
      lane_dest_prov: lane.dest_prov,
      metro_matched:
        lane.origin_city !== oCity || lane.dest_city !== dCity,
    });
  }
  quotes.sort((a, b) => a.total_cad - b.total_cad || a.carrier_id.localeCompare(b.carrier_id));
  return quotes;
}

// Carrier directory with live lane counts.
function listCarriers() {
  const st = ensureLoaded();
  const counts = new Map();
  for (const lane of st.data.lanes) {
    counts.set(lane.carrier_id, (counts.get(lane.carrier_id) || 0) + 1);
  }
  const out = [];
  for (const c of st.data.carriers) {
    const ov = _fscOverrides.get(c.carrier_id);
    out.push({
      carrier_id: c.carrier_id,
      carrier_label: c.carrier_label,
      lane_count: counts.get(c.carrier_id) || 0,
      // Effective (live) FSC percents: admin override wins over rate sheet.
      fsc_ltl_percent: ov && Number.isFinite(ov.ltl) ? ov.ltl : (Number(c.fsc_percent) || 0),
      fsc_tl_percent: ov && ov.tl != null && Number.isFinite(ov.tl) ? ov.tl
        : (c.carrier_id === 'rosenau' ? ROSENAU_TL_FSC : c.carrier_id === 'teams' ? TEAMS_FSC_TL : null),
      fsc_overridden: !!(ov && Number.isFinite(ov.ltl)),
      fsc_percent: c.fsc_percent, // rate-sheet value, for reference
      fsc_cadence: c.fsc_cadence || null, // 'weekly' | 'monthly' | 'per_sheet'
      fsc_as_of: (ov && ov.updated_at) || c.fsc_as_of,
    });
    counts.delete(c.carrier_id);
  }
  // Carrier ids introduced via upsertCarrierRows without a carriers entry.
  for (const [id, n] of counts) {
    out.push({ carrier_id: id, carrier_label: id, lane_count: n, fsc_percent: 0, fsc_as_of: null });
  }
  return out;
}

// Accessorials for a carrier ([] when the carrier has none).
function getAccessorials(carrierId) {
  const st = ensureLoaded();
  return st.data.accessorials.filter((a) => a.carrier_id === carrierId);
}

// Merge canonical lane rows into the in-memory matrix.
// rows: [{origin_city, origin_prov, dest_city, dest_prov, min_charge_cad,
//          breaks:[{max_lb, rate_cwt}, ...],
//          flat_bands:[{max_lb, price_cad}, ...] (per-shipment flat bands),
//          per_unit_bands:[{max_lb, price_cad}, ...] (per-unit price by unit weight),
//          service_days?}]
// Same origin/dest lane is replaced; new lanes are appended.
// Returns the number of rows successfully upserted.
// NOTE: in-memory only — the caller (e.g. the upload endpoint) must persist.
// Register (or update) a carrier record in the in-memory matrix, e.g. for
// carriers onboarded via self-serve uploads whose lanes live in the DB
// rather than matrix-data.json. Returns the carrier_id.
function upsertCarrier(carrier) {
  const st = ensureLoaded();
  const carrier_id = String((carrier && carrier.carrier_id) || '').trim();
  if (!carrier_id) return null;
  const rec = {
    carrier_id,
    carrier_label: String(carrier.carrier_label || carrier_id).trim() || carrier_id,
    fsc_percent: carrier.fsc_percent == null ? 0 : Number(carrier.fsc_percent) || 0,
    fsc_as_of: carrier.fsc_as_of || null,
    fsc_cadence: carrier.fsc_cadence || null,
    fsc_note: carrier.fsc_note || null,
  };
  const i = st.data.carriers.findIndex((c) => c.carrier_id === carrier_id);
  if (i >= 0) st.data.carriers[i] = { ...st.data.carriers[i], ...rec };
  else {
    st.data.carriers.push(rec);
    st.carriersById.set(carrier_id, st.data.carriers[st.data.carriers.length - 1]);
  }
  return carrier_id;
}

function upsertCarrierRows(carrierId, rows) {  const st = ensureLoaded();
  if (!Array.isArray(rows)) return 0;
  let count = 0;
  for (const r of rows) {
    if (!r || typeof r !== 'object') continue;
    const origin_city = norm(r.origin_city);
    const origin_prov = norm(r.origin_prov);
    const dest_city = norm(r.dest_city);
    const dest_prov = norm(r.dest_prov);
    const min_charge_cad = Number(r.min_charge_cad);
    const breaks = Array.isArray(r.breaks)
      ? r.breaks
          .map((b) => {
            const o = { max_lb: Number(b && b.max_lb), rate_cwt: Number(b && b.rate_cwt) };
            const mn = Number(b && b.min_lb);
            if (Number.isFinite(mn) && mn > 0) o.min_lb = mn;
            return o;
          })
          .filter((b) => Number.isFinite(b.max_lb) && b.max_lb > 0 && Number.isFinite(b.rate_cwt) && b.rate_cwt > 0)
          .sort((a, b) => a.max_lb - b.max_lb)
      : [];
    const flat_bands = Array.isArray(r.flat_bands)
      ? r.flat_bands
          .map((b) => {
            const o = { max_lb: Number(b && b.max_lb), price_cad: Number(b && b.price_cad) };
            const mn = Number(b && b.min_lb);
            if (Number.isFinite(mn) && mn > 0) o.min_lb = mn;
            return o;
          })
          .filter((b) => Number.isFinite(b.max_lb) && b.max_lb > 0 && Number.isFinite(b.price_cad) && b.price_cad > 0)
          .sort((a, b) => a.max_lb - b.max_lb)
      : [];
    const skid_rates = r.skid_rates && typeof r.skid_rates === 'object'
      ? Object.fromEntries(Object.entries(r.skid_rates)
          .map(([k, v]) => [Number(k), Number(v)])
          .filter(([k, v]) => Number.isInteger(k) && k > 0 && Number.isFinite(v) && v > 0))
      : null;
    const per_unit_bands = Array.isArray(r.per_unit_bands)
      ? r.per_unit_bands
          .map((b) => {
            const o = { max_lb: Number(b && b.max_lb), price_cad: Number(b && b.price_cad) };
            const mn = Number(b && b.min_lb);
            if (Number.isFinite(mn) && mn > 0) o.min_lb = mn;
            return o;
          })
          .filter((b) => Number.isFinite(b.max_lb) && b.max_lb > 0 && Number.isFinite(b.price_cad) && b.price_cad > 0)
          .sort((a, b) => a.max_lb - b.max_lb)
      : [];
    if (!origin_city || !dest_city || !Number.isFinite(min_charge_cad) || min_charge_cad < 0 || (breaks.length === 0 && flat_bands.length === 0 && !skid_rates && per_unit_bands.length === 0 && !(Number(r.flat_per_piece_cad) > 0) && !(Array.isArray(r.per_piece_tiers) && r.per_piece_tiers.length > 0))) continue;

    const lane = { carrier_id: carrierId, origin_city, origin_prov, dest_city, dest_prov, min_charge_cad, breaks };
    if (flat_bands.length) lane.flat_bands = flat_bands;
    if (skid_rates) lane.skid_rates = skid_rates;
    if (per_unit_bands.length) lane.per_unit_bands = per_unit_bands;
    if (Number(r.flat_per_piece_cad) > 0) {
      lane.flat_per_piece_cad = Number(r.flat_per_piece_cad);
      lane.min_pieces = Math.max(1, Math.floor(Number(r.min_pieces) || 1));
    }
    if (Array.isArray(r.per_piece_tiers) && r.per_piece_tiers.length > 0) {
      lane.per_piece_tiers = r.per_piece_tiers
        .map((t) => ({ max_od_in: Number(t && t.max_od_in), price_cad: Number(t && t.price_cad) }))
        .filter((t) => Number.isFinite(t.max_od_in) && t.max_od_in > 0 && Number.isFinite(t.price_cad) && t.price_cad > 0)
        .sort((a, b) => a.max_od_in - b.max_od_in);
      lane.min_pieces = Math.max(1, Math.floor(Number(r.min_pieces) || 1));
    }
    if (Number.isFinite(Number(r.service_days))) lane.service_days = Number(r.service_days);

    const key = laneKey(carrierId, origin_city, origin_prov, dest_city, dest_prov);
    if (st.laneIndex.has(key)) {
      st.data.lanes[st.laneIndex.get(key)] = lane;
    } else {
      st.laneIndex.set(key, st.data.lanes.length);
      st.data.lanes.push(lane);
    }
    count++;
  }
  return count;
}

module.exports = { loadMatrix, quoteMatrix, quoteFtl, billableWeight, guilbaultBillableWeight, fullLoadCheck, densityFloorFor, setDensityFloor, clearDensityFloor, getDensityFloors, dimWeightEnabledFor, setDimWeightEnabled, getDimWeightFlags, listCarriers, getAccessorials, upsertCarrier, upsertCarrierRows, suggestCity, setFscOverride, clearFscOverride, getFscOverrides, primeTimeDeliveryQuotes, primeTimeAfterHoursQuote, primeTimeTruckQuote, primeTimeHotShotQuote, number8Quotes, doneDealQuotes, knrQuotes, teamsQuotes, mayServeLanes };
